import sqlite3
import json

conn = sqlite3.connect('/workspace/world.db')
cur = conn.cursor()
cur.execute('SELECT key, value FROM ts_retail_products')
rows = cur.fetchall()
print(f'Total product entries: {len(rows)}')

for key, val in rows:
    try:
        data = json.loads(val)
    except:
        data = val
    data_str = str(data).lower()
    if any(kw in data_str for kw in ['mouse', 'logitech', 'fa0948', 'm310', 'wireless mouse']):
        print(f'MATCH key={key}:')
        print(json.dumps(data, indent=2) if isinstance(data, (dict, list)) else data)
        print()

# Print first 3 for format reference
print('\nFirst 3 entries:')
for key, val in rows[:3]:
    try:
        data = json.loads(val)
    except:
        data = val
    if isinstance(data, dict):
        print(f'  key={key}, name={data.get("name", "?")}, id={data.get("product_id", "?")}')
    else:
        print(f'  key={key}, val_preview={str(data)[:200]}')

conn.close()

